from __future__ import annotations
import base64
import hashlib
import json
import zlib

_PAYLOAD_B64 = """"""
_COMPRESSED_SHA256 = "aa3cd4e3162f0f457d684b9c1d57ec76aa27c32ee87df14c33cd052c2829f34e"
_JSON_SHA256 = "5d34dc72a3175c6c4390d07219cb2f06a8e18c1b09bd16cff079ffd52a6ae241"
_EXPECTED_CASE_COUNT = 94


def load_cases():
    compressed = base64.b64decode(_PAYLOAD_B64)
    if hashlib.sha256(compressed).hexdigest() != _COMPRESSED_SHA256:
        raise RuntimeError("sealed case compressed payload hash mismatch")
    raw = zlib.decompress(compressed)
    if hashlib.sha256(raw).hexdigest() != _JSON_SHA256:
        raise RuntimeError("sealed case JSON hash mismatch")
    cases = json.loads(raw)
    if len(cases) != _EXPECTED_CASE_COUNT:
        raise RuntimeError("sealed case count mismatch")
    ids = [case["id"] for case in cases]
    if len(set(ids)) != len(ids):
        raise RuntimeError("duplicate sealed case id")
    return cases


CASES = load_cases()
